#include <stdio.h>
#include <string.h>

int main() {
    // Mapeamento de 'a' a 'z' para o dígito correspondente no teclado telefônico
    const char char_to_digit[26] = {
        '2', '2', '2', // a, b, c
        '3', '3', '3', // d, e, f
        '4', '4', '4', // g, h, i
        '5', '5', '5', // j, k, l
        '6', '6', '6', // m, n, o
        '7', '7', '7', '7', // p, q, r, s
        '8', '8', '8', // t, u, v
        '9', '9', '9', '9'  // w, x, y, z
    };

    char n[1005];
    if (scanf("%1004s", n) != 1) return 0;

    int len_n = strlen(n);

    int m;
    if (scanf("%d", &m) != 1) return 0;

    int count = 0;
    char c[1005];

    for (int i = 0; i < m; i++) {
        scanf("%1004s", c);
        int len_c = strlen(c);

        if (len_c != len_n) {
            continue;
        }

        int matches = 1;
        for (int j = 0; j < len_n; j++) {
            if (char_to_digit[c[j] - 'a'] != n[j]) {
                matches = 0;
                break;
            }
        }

        if (matches) {
            count++;
        }
    }

    printf("%d\n", count);

    return 0;
}
